-- Kalo · los dos chocolates en leche con la MISMA base: 1 pastilla de chocolate de mesa (25 g) + 1 taza de leche entera (240 g).
-- El sin azúcar es el mismo chocolate sin su azúcar (endulzado sin calorías). Antes el normal era un chocolate de EE. UU. con cacao en polvo
-- y el sin azúcar, cacao puro: por eso el sin azúcar salía con más calorías.
update public.plan_items set cantidad = cantidad * 250.0 / 265.0 where alimento_id = 'chocolate-caliente';
update public.opcion_items set cantidad = cantidad * 250.0 / 265.0 where alimento_id = 'chocolate-caliente';
update public.alimentos set por_100g = '{"zinc_mg": 0.525, "vit_d_ug": 1.177, "grasa_sat_g": 2.637, "b12_ug": 0.429, "b2_mg": 0.159, "proteina_g": 3.192, "vit_e_mg": 0.114, "b1_mg": 0.048, "b6_mg": 0.04, "kcal": 100.528, "carbos_g": 11.894, "potasio_mg": 172.283, "sodio_mg": 38.943, "grasa_g": 4.453, "vit_k_ug": 1.036, "colesterol_mg": 9.057, "fosforo_mg": 95.509, "fibra_g": 0.66, "manganeso_mg": 0.134, "selenio_ug": 3.634, "magnesio_mg": 22.83, "vit_c_mg": 0.0, "calcio_mg": 107.623, "folato_ug": 4.528, "cobre_mg": 0.124, "b3_mg": 0.15, "azucar_g": 10.989, "hierro_mg": 0.784, "vit_a_ug": 41.849, "azucar_libre_g": 6.42}'::jsonb,
  fuente = 'Receta Kalo: 1 pastilla de chocolate de mesa (25 g) + 1 taza de leche entera (240 g). Etiqueta Chocolate Corona tradicional',
  porcion_base = '{"texto": "1 taza (1 pastilla)", "gramos": 265}'::jsonb, porciones = '[{"texto": "1 taza (1 pastilla)", "gramos": 265}, {"texto": "1 pocillo pequeño", "gramos": 180}, {"texto": "100 g", "gramos": 100}]'::jsonb where id = 'chocolate-caliente';
